actions.script:
const out = ec.service.sync().name('org.moqui.impl.CallServices.join#AsGuest').parameters({token: token || '',
    displayName: displayName || ''}).requireNewTransaction(true).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, credential: out.credential || null,
    callSessionId: out.callSessionId || null, callLegId: out.callLegId || null, admission: out.admission || null})

const check = ec.service.sync().name('org.moqui.impl.CallServices.check#CallLinkToken').parameter('token', token || '').call() || {}
const out = check.valid ? ec.service.sync().name('org.moqui.impl.CallServices.get#GuestState').parameter('credential', credential || '')
    .requireNewTransaction(true).call() || {} : {admission: 'gone'}
ec.message.clearErrors()
ec.web.sendJsonResponse({admission: out.admission || 'gone', callStatus: out.callStatus || null, people: out.people || []})

const check = ec.service.sync().name('org.moqui.impl.CallServices.check#CallLinkToken').parameter('token', token || '').call() || {}
const out = check.valid ? ec.service.sync().name('org.moqui.impl.CallServices.get#GuestIceServers').parameter('credential', credential || '')
    .requireNewTransaction(true).call() || {} : {}
ec.message.clearErrors()
ec.web.sendJsonResponse({iceServers: out.iceServers || []})
